import React, { useState, useEffect } from "react";
import InputField from "../components/InputField";

const PersonFilter = ({ filter, setFilter }) => {
    const [localFilter, setLocalFilter] = useState(filter);

    useEffect(() => {
        setFilter(localFilter);
    }, [localFilter, setFilter]); // Aplikace filtru při každé změně hodnoty

    const handleChange = (e) => {
        setLocalFilter((prev) => ({ ...prev, [e.target.name]: e.target.value }));
    };

    return (
        <form onSubmit={(e) => e.preventDefault()}>   
            <div className="row">
                <div className="col-9">
                    <InputField
                        type="text"
                        name="identificationNumber"
                        handleChange={handleChange}
                        label="Identifikační číslo"
                        prompt="-"
                        value={localFilter.identificationNumber || ""}
                    />
                </div>
                <div className="col-3">
                    <InputField
                        type="number"
                        min="1"
                        name="limit"
                        handleChange={handleChange}
                        label="Počet osob na stránku"
                        value={localFilter.limit || "5"}
                    />
                </div>
            </div>
        </form>
    );
};

export default PersonFilter;
